// One actual new B3 raw with the unchanged B2 captions/private compositor.
import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import {createHash} from 'node:crypto';
import sharp from 'sharp';
const base='/private/tmp/ys/ys-chain-b1v1-final2-20261024';
const probe='/private/tmp/ys/ys-chain-b1v1-challenge-b3-v2-20261024/probe';
const out=probe+'/actual-caption-review',cache=out+'/cache';
const sha=p=>createHash('sha256').update(fs.readFileSync(p)).digest('hex');
assert(!fs.existsSync(out),'Preserve previous actual-caption review');
const pr=JSON.parse(fs.readFileSync(probe+'/report.json'));
assert.equal(pr.status,'two_actual_probes_pending_eye_review');
assert.equal(pr.actualOutputFrame,10185);
assert.equal(pr.actualHeldSourceFrame,10178);
const protectedPaths=[base+'/plan.json',base+'/ys-chain-b1v1.json',base+'/phrase-times.json',base+'/blender/data.json',probe+'/actual-339500.jpg',probe+'/anchors.json',probe+'/report.json','scripts/umech/desk-b1v1-review-frame.mjs','scripts/umech/desk-b1v1-review-overlay.mjs','scripts/umech/desk-b1v1-overlay.mjs'];
const hashes=Object.fromEntries(protectedPaths.map(p=>[path.resolve(p),sha(p)]));
fs.mkdirSync(cache+'/blender/desk',{recursive:true});
for(const name of ['plan.json','ys-chain-b1v1.json','phrase-times.json'])fs.symlinkSync(base+'/'+name,cache+'/'+name);
fs.symlinkSync(base+'/blender/data.json',cache+'/blender/data.json');
fs.symlinkSync(probe+'/actual-339500.jpg',cache+'/blender/desk/10185.jpg');
fs.symlinkSync(probe+'/anchors.json',cache+'/blender/desk/anchors.json');
process.env.EM_FILM_CACHE=cache;
const {vertFrame}=await import('./desk-b1v1-review-frame.mjs');
const plan=JSON.parse(fs.readFileSync(cache+'/plan.json'))[0],timed=JSON.parse(fs.readFileSync(cache+'/ys-chain-b1v1.json'));
const clip={...plan,duration:timed.duration,scenes:plan.scenes.map((s,i)=>({...s,start:timed.scenes[i].start,end:timed.scenes[i].end,captions:timed.scenes[i].captions}))};
const t=339.5,scene=clip.scenes.find(s=>t>=s.start&&t<s.end);
assert(scene);
const svg=vertFrame(clip,scene,t);
assert(!/NaN|undefined|Infinity/.test(svg));
const png=out+'/actual-339500-caption.png';
await sharp(Buffer.from(svg)).png().toFile(png);
for(const [p,h]of Object.entries(hashes))assert.equal(sha(p),h,p);
fs.writeFileSync(out+'/provenance.json',JSON.stringify({candidate:'B3 v2 probe, not final MP4',time:t,actualOutputFrame:10185,actualHeldSourceFrame:10178,actualRaw:probe+'/actual-339500.jpg',output:png,outputSha256:sha(png),protectedInputSha256:hashes,actualEyeReviewPerformed:false,approved:false},null,1));
console.log(png);
